const table = context.get('table');
const WATER = context.get('WATER');
const AIR = context.get('AIR');
const { metadata, rows } = msg.payload;

msg.payload = {
    metadata,
    rows: rows.map(r => {
        const scope = (r.scope || 'WATER').toUpperCase();
        if (scope === 'SOURCE') {
            return { ...r, parameter: r.parameter_raw, unit: r.unit_raw };
        }
        const needle = (r.parameter_raw || '').toLowerCase();
        const cats = scope === 'AIR' ? AIR : WATER;
        const hit = table.find(x =>
            (x.variable.includes(needle) || x.longName.includes(needle))
            && cats.has(x.category)
        );
        return hit
            ? { ...r, parameter: hit.stdName, unit: hit.unit }
            : { ...r, parameter: r.parameter_raw, unit: r.unit_raw };
    })
};
return msg;

