const text = fs.readFileSync(env.get('CSV_PATH'), 'utf8');
const lines = text.split(/\r?\n/).filter(l => l.trim());
const header = lines[0].split(',');
const idx = name => header.indexOf(name);
const cCat = idx('Category');
const cVar = idx('variable name');
const cLong = idx('long_name');
const cUnit = idx('unit');
const cStd = idx('CF standard_name');

const table = lines.slice(1).map(l => {
    const c = l.split(',');
    return {
        category: (c[cCat] || '').toLowerCase(),
        variable: (c[cVar] || '').toLowerCase(),
        longName: (c[cLong] || '').toLowerCase(),
        unit: c[cUnit] || '',
        stdName: c[cStd] || ''
    };
});

context.set('table', table);
context.set('WATER', new Set(['physical oceanography', 'bgc', 'sea level', 'waves']));
context.set('AIR', new Set(['meteorological']));

