const { metadata, rows } = msg.payload;
const formatVersion = env.get('FORMAT_VERSION') || 'SMARTOCEAN_V1';
const assignDpId    = (env.get('ASSIGN_DP_ID') || '').toLowerCase() === 'true';

const groups = new Map();
for (const r of rows) {
    const locKey = r.location
        ? `${r.location.latitude},${r.location.longitude}`
        : 'null';
    const key = `${r.time}|${locKey}|${r.hub_source_id}`;

    if (!groups.has(key)) {
        // Field order matches pydantic DataPoint declaration order.
        // null is emitted explicitly for optional fields to mirror pydantic JSON dump.
        const dp = {
            dp_id:     null,
            source:    r.hub_source    ?? null,
            source_id: r.hub_source_id,
            location:  r.location      ?? null,
            time:      r.time,
            observations: []
        };
        groups.set(key, dp);
    }

    // Field order matches pydantic Observation declaration order.
    const obs = {
        source:       r.sensor_source ?? null,
        source_id:    r.sensor_id,
        parameter:    r.parameter,
        value:        r.value,
        unit:         r.unit,
        qualityCodes: r.qualityCodes || [0]
    };
    groups.get(key).observations.push(obs);
}

const dataPoints = Array.from(groups.values());
if (assignDpId) {
    dataPoints.forEach((dp, i) => { dp.dp_id = String(i + 1); });
}

msg.payload = {
    format: formatVersion,
    metadata: metadata,
    data: dataPoints
};
return msg;

const validate = context.get('validate');
if (validate(msg.payload)) return [msg, null];
msg.error = JSON.stringify(validate.errors);
return [null, msg];

