const device = msg.payload.Device;
if (!device) { msg.error = 'missing <Device>'; return [null, msg]; }

const attr = device.$ || {};
if (!attr.Descr)     { msg.error = 'missing Device @Descr';     return [null, msg]; }
if (!attr.ID)        { msg.error = 'missing Device @ID';        return [null, msg]; }
if (!attr.SessionID) { msg.error = 'missing Device @SessionID'; return [null, msg]; }

const deviceDescr = attr.Descr;
const deviceId    = attr.ID;
const sessionId   = attr.SessionID;

if (!device.SystemInformation) {
    msg.error = 'missing <SystemInformation>';
    return [null, msg];
}
const sysInfoContainer = device.SystemInformation?.[0];
if (!sysInfoContainer || typeof sysInfoContainer !== 'object' || !sysInfoContainer.SystemInfo) {
    msg.error = 'missing <SystemInfo>';
    return [null, msg];
}
const sysInfoList = sysInfoContainer.SystemInfo;
const findSysInfo = (descr) => {
    const hit = sysInfoList.find(i => i.$?.Descr === descr);
    return hit?._ || '';
};
const locationDescr = findSysInfo('Location ');
const geoPosition   = findSysInfo('GeoPosition');

let location = null;
const parts = (geoPosition || '').split(',');
if (parts.length === 2) {
    const lat = parseFloat(parts[0]);
    const lon = parseFloat(parts[1]);
    if (!isNaN(lat) && !isNaN(lon)) location = { latitude: lat, longitude: lon };
}

const data = device.Data?.[0];
if (!data) { msg.error = 'missing <Data>'; return [null, msg]; }
if (!data.Time || !data.Time[0])  { msg.error = 'missing <Data><Time>';  return [null, msg]; }
if (!data.SensorData)             { msg.error = 'missing <SensorData>';  return [null, msg]; }
if (!data.SystemData)             { msg.error = 'missing <SystemData>';  return [null, msg]; }

const dataTime = data.Time[0].replace('Z', '+00:00');

let sensors = [...data.SensorData];
const sysList = Array.isArray(data.SystemData) ? data.SystemData : [data.SystemData];
sensors.push(...sysList);

const rows = [];
for (const sensor of sensors) {
    if (!sensor.$?.ID)      { msg.error = 'sensor missing @ID';          return [null, msg]; }
    if (!sensor.Parameters) { msg.error = 'sensor missing <Parameters>'; return [null, msg]; }
    const params = sensor.Parameters?.[0];
    if (!params?.Point)     { msg.error = 'sensor missing <Point>';      return [null, msg]; }

    const sensorId    = sensor.$.ID;
    const sensorDescr = sensor.$.Descr || '';
    const points = Array.isArray(params.Point) ? params.Point : [params.Point];
    for (const point of points) {
        const valueEl = point.Value;
        if (valueEl === undefined || valueEl === null) continue;
        const value = Array.isArray(valueEl) ? valueEl[0] : valueEl;
        rows.push({
            time: dataTime,
            location,
            hub_source_id: deviceId,
            hub_source:    deviceDescr,
            sensor_id:     sensorId,
            sensor_source: sensorDescr,
            parameter_raw: point.$?.Descr || '',
            value:         String(value),
            unit_raw:      point.$?.Unit || '',
            scope:         'SOURCE'
        });
    }
}

msg.payload = {
    metadata: {
        description: locationDescr ? `${deviceDescr}: ${locationDescr}` : deviceDescr,
        timeseries: sessionId,
        origin: sessionId
    },
    rows
};
return [msg, null];

// Faithful to Python's validate_wsense_format → validate_json_str: just confirm it parses.
let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    msg.error = 'WSense JSON parse: ' + e.message;
    return [null, msg];
}
msg.payload = parsed;
return [msg, null];

const payload = msg.payload;
const definitions = payload.definitions || [];

if (!payload.nodes) {
    msg.error = 'WSense: missing <nodes>';
    return [null, msg];
}

const getDefUnit = (defs, name) => {
    const d = defs.find(x => x && x.name === name);
    return d ? (d.unit ?? null) : null;
};

// Preserve microsecond precision from the input string when it's UTC.
// Python normalizes to UTC (with µs precision); JS Date only does ms,
// so we only pass through when the input is already UTC.
function toUtcIso(ts) {
    if (typeof ts === 'string') {
        // Mirror Python's datetime.isoformat(): drop fractional seconds when all zeros
        let s = ts.replace(/\.0+(?=Z|[+-])/, '');
        if (s.endsWith('+00:00')) return s;
        if (s.endsWith('Z'))      return s.slice(0, -1) + '+00:00';
    }
    const d = new Date(ts);
    if (isNaN(d.getTime())) throw new Error('bad date: ' + ts);
    return d.toISOString().replace('Z', '+00:00');     // fallback (lossy)
}

const rows = [];
let metadata = null;

for (const wrap of payload.nodes) {
    const node = wrap?.node;
    if (!node) { msg.error = 'WSense: missing node.node'; return [null, msg]; }
    const coords = node.coordinates;
    if (!coords) { msg.error = 'WSense: missing node.coordinates'; return [null, msg]; }
    const location = { latitude: coords.latitude, longitude: coords.longitude };

    metadata = {
        description: 'Wsense data from B2B API',
        timeseries: 'wsense',
        origin: node.name
    };

    const sourceIdByTree = {};
    const sourceLabelByTree = {};
    for (const probe of (node.children || [])) {
        sourceIdByTree[probe.treeId] = probe.id;
        sourceLabelByTree[probe.treeId] = `${probe.name} ${probe.type}`;
    }

    if (!Array.isArray(node.data)) {
        msg.error = 'WSense: missing node.data';
        return [null, msg];
    }

    for (const paramWrap of node.data) {
        const entries = Object.entries(paramWrap);
        for (const [paramName, paramVal] of entries) {
            const unitRaw = getDefUnit(definitions, paramName);
            if (unitRaw === null || unitRaw === undefined) {
                msg.error = "WSense: missing unit in definitions for '" + paramName + "'";
                return [null, msg];
            }
            const scope = unitRaw.toLowerCase().includes('battery') ? 'SOURCE' : 'WATER';

            const dataArr = paramVal?.data;
            if (!Array.isArray(dataArr)) continue;

            for (const dp of dataArr) {
                let time;
                try { time = toUtcIso(dp.timestamp); }
                catch (e) { msg.error = 'WSense: ' + e.message; return [null, msg]; }
                const sensorId    = sourceIdByTree[dp.probe_type] || '';
                const sensorLabel = sourceLabelByTree[dp.probe_type] || '';
                rows.push({
                    time,
                    location,
                    hub_source_id: node.id,
                    hub_source:    node.name,
                    sensor_id:     sensorId,
                    sensor_source: sensorLabel,
                    parameter_raw: paramName,
                    value:         dp.value,
                    unit_raw:      unitRaw,
                    scope
                });
            }
        }
    }
}

msg.payload = { metadata, rows };
return [msg, null];

// Virtual: input is already SmartOcean JSON. Parse and pass through.
let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    msg.error = 'Virtual JSON parse: ' + e.message;
    return [null, msg];
}
msg.payload = parsed;
return [msg, null];

// Append /raw suffix to msg.topic, stripping /in if present.
// Returns null if topic is empty (e.g., file-in trigger) so we don't publish junk.
const t = msg.topic || '';
if (!t) return null;
msg.topic = t.endsWith('/in') ? t.slice(0, -3) + '/raw' : t + '/raw';
return msg;

