function testDirectory(dir, expectError, expectedFailures = new Set()) {
    return fs.readdirSync(dir)
        .filter(f => f.endsWith('.xml'))
        .map((f, i) => {
            const shouldError = expectError || expectedFailures.has(f);
            return {
                label: `${shouldError ? 'should error' : 'should pass'}: ${f}`,
                delay: 100 + i * 20,
                timeout: 80000,
                inject: { filename: path.join(dir, f) },
                assert: function(msg) {
                    if (shouldError) {
                        should(msg).have.property('error');
                    } else {
                        should(msg).not.have.property('error');
                        should(msg.payload).have.property('format', 'SMARTOCEAN_V1');
                    }
                }
            };
        });
}

