// Append /raw suffix to msg.topic, stripping /in if present.
// Returns null if topic is empty (e.g., file-in trigger) so we don't publish junk.
const t = msg.topic || '';
if (!t) return null;
msg.topic = t.endsWith('/in') ? t.slice(0, -3) + '/raw' : t + '/raw';
return msg;

// Faithful to Python validate_fluorometer_format:
//   - JSON parses
//   - top-level required keys present
let parsed;
try {
    parsed = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    msg.error = 'Fluorometer JSON parse: ' + e.message;
    return [null, msg];
}
const required = ['device_id','device_type','deployment','location','measured_at','measurements'];
const missing = required.filter(k => !(k in parsed));
if (missing.length) {
    msg.error = 'Fluorometer payload missing required keys: ' + JSON.stringify(missing);
    return [null, msg];
}
msg.payload = parsed;
return [msg, null];

// Project fluorometer payload to the canonical row contract consumed
// by cmems-standard + assemble-timeseries.

const payload = msg.payload;
const unitBySuffix = { ugl: 'ug/L', ntu: 'NTU', qsde: 'QSDE' };

function splitField(field) {
    if (!field.includes('_')) return [field, ''];
    const idx = field.lastIndexOf('_');
    const base = field.slice(0, idx);
    const suffix = field.slice(idx + 1).toLowerCase();
    const unit = unitBySuffix[suffix];
    return unit ? [base, unit] : [field, ''];
}

// CMEMS table uses hyphenated names ("Chlorophyll-a"). The substring lookup
// won't match "chlorophyll_a", so swap underscores for hyphens to give the
// lookup a chance.
function normaliseForCmems(base) {
    return base.replace(/_/g, '-');
}

// Mirror Python's datetime.isoformat() when it's already UTC: drop fractional
// zero seconds, normalise trailing Z to +00:00.
function toUtcIso(ts) {
    if (typeof ts === 'string') {
        let s = ts.replace(/\.0+(?=Z|[+-])/, '');
        if (s.endsWith('+00:00')) return s;
        if (s.endsWith('Z'))      return s.slice(0, -1) + '+00:00';
    }
    const d = new Date(ts);
    if (isNaN(d.getTime())) throw new Error('bad date: ' + ts);
    return d.toISOString().replace('Z', '+00:00');
}

const deviceId   = payload.device_id;
const deviceType = payload.device_type;
const deployment = payload.deployment;
const loc        = payload.location;
const measuredAt = payload.measured_at;
const measurements  = payload.measurements   || {};
const qualityFlags  = payload.quality_flags  || {};

const metadata = {
    description: `${deviceType}: ${deployment}`,
    timeseries:  deviceId,
    origin:      deviceId,
};

const time     = toUtcIso(measuredAt);
const location = { latitude: loc.lat, longitude: loc.lon };

const rows = [];
for (const [field, value] of Object.entries(measurements)) {
    const [base, unitRaw] = splitField(field);
    rows.push({
        scope:          'WATER',
        parameter_raw:  normaliseForCmems(base),
        unit_raw:       unitRaw,
        value:          value,
        qualityCodes:   [qualityFlags[base] ?? 0],
        time:           time,
        location:       location,
        hub_source:     deviceType,
        hub_source_id:  deviceId,
        sensor_source:  deviceType,
        sensor_id:      deviceId,
    });
}

msg.payload = { metadata, rows };
return [msg, null];

// Append /raw suffix to msg.topic, stripping /in if present.
// Returns null if topic is empty (file-in trigger) so we don't publish junk.
const t = msg.topic || '';
if (!t) return null;
msg.topic = t.endsWith('/in') ? t.slice(0, -3) + '/raw' : t + '/raw';
return msg;

// One input, one output.
// SCALE and OFFSET are environment variables declared on the
// subflow definition; each instance supplies its own values.
const scale  = parseFloat(env.get("SCALE"))  || 1;
const offset = parseFloat(env.get("OFFSET")) || 0;

msg.payload = msg.payload * scale + offset;
return msg;
